-- Daily cloud recovery backups; no trading authority or historical bars move.
create schema if not exists quant_cloud_jobs;
revoke all on schema quant_cloud_jobs from public, anon, authenticated;
create table if not exists quant_cloud_jobs.coordination_backup_slots (
    slot integer primary key check (slot between 1 and 31),
    result jsonb not null,
    updated_at timestamptz not null default now()
);
revoke all on quant_cloud_jobs.coordination_backup_slots from public, anon, authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('coordination-backups', 'coordination-backups', false, 1048576, array['application/gzip'])
on conflict (id) do update set public=false, file_size_limit=1048576, allowed_mime_types=array['application/gzip'];

create or replace function public.quant_export_coordination_backup() returns text
language sql stable security definer
set search_path = pg_catalog
as $backup$
select case when (
    select jsonb_object_agg(table_name, columns) from (
        select table_name, jsonb_agg(column_name order by column_name) as columns
        from information_schema.columns where table_schema='quant_coordination'
        group by table_name
    ) schema_columns
) = '{"app_runtime_status":["active","heartbeat_at","hostname","pid","process_name","started_at"],"app_state_sync":["payload","revision","state_key","updated_at","updated_by_device","updated_by_host"],"application_heartbeat_attempts":["attempted_at","device_id","error","id","provider_delivery_id","status"],"capital_reservation_accounts":["account_no","environment","updated_at"],"capital_reservations":["absence_count","account_no","attempt_group_id","created_at","environment","last_absence_observed_at","last_absence_session_date","last_absence_snapshot_id","projected_open_risk","released_at","remaining_projected_open_risk","remaining_reserved_notional","requested_notional","reservation_id","status","symbol","updated_at","version"],"daily_trading_events":["account_no","environment","event_key","event_type","id","occurred_at","payload","session_date","symbol"],"discovered_external_orders":["account_no","broker_identity_key","broker_order_id","disposition","environment","external_order_id","id","payload","symbol","updated_at","version"],"emergency_journal_reconciliation":["id","idempotency_key","journal_id","payload","reconciled_at","request_checksum","requested_sequence"],"execution_commands":["account_no","command_type","environment","id","idempotency_key","lease_epoch","lease_token","owner_device_id","redacted_response","requested_at","response_hash","source","status","symbol","target_broker_order_id","version"],"execution_orders":["account_no","adopted_from_external_order_id","broker_identity_key","broker_identity_status","broker_order_id","client_order_id","environment","id","origin","payload","recovery_state","status","symbol","updated_at","version"],"execution_ownership":["account_no","assigned_by","environment","id","owner","strategy_instance_id","symbol","updated_at","version"],"execution_schema_migration":["backup_checksum","backup_path","created_at","cutover_device_id","cutover_lease_epoch","cutover_lease_token","last_error","phase","post_migration_broker_mutation_occurred","reconciliation_complete","singleton_id","source_version","target_version","updated_at","version"],"external_alert_delivery_attempts":["attempt_number","attempted_at","error","escalation_level","id","incident_id","provider_delivery_id","status"],"external_alert_incidents":["acknowledged_at","acknowledged_by","alert_type","created_at","dedupe_key","delivery_attempt_count","escalation_level","incident_id","message","next_attempt_at","occurrence_count","status","updated_at","version"],"external_alert_spool_imports":["imported_at","incident_id","pending_event_id"],"live_trading_control_audit":["enabled","previous_enabled","revision","updated_at","updated_by_device","updated_by_host"],"operator_commands":["accepted_at","broker_order_id","broker_submitted_at","command_id","command_type","completed_at","created_at","error_message","executing_at","executor_device_id","executor_host","failed_at","idempotency_key","payload_json","rejected_at","requested_by_device","requested_by_host","state_after_hash","state_before_hash","status","symbol"],"operator_control_audit":["locked","new_device_id","new_hostname","previous_device_id","previous_hostname","revision","updated_at","updated_by_device","updated_by_host"],"runtime_device_state":["confirmed_at","confirmed_by_lease_epoch","confirmed_generation","details_json","device_id","handoff_confirmed","hostname","readiness_generation","schema_version","state","updated_at"],"trade_cards":["account_no","board_status","environment","id","payload","symbol","updated_at","version"]}'::jsonb then
jsonb_build_object('format','quant-coordination-backup-v1','tables',jsonb_build_object(
'app_runtime_status',
(select coalesce(jsonb_agg(jsonb_build_object('hostname',t."hostname",'process_name',t."process_name",'pid',t."pid",'active',t."active",'started_at',case when t."started_at" is null then null else jsonb_build_object('__schema_migration_value_type__','datetime','value',to_char(t."started_at",'YYYY-MM-DD"T"HH24:MI:SS.US')) end,'heartbeat_at',case when t."heartbeat_at" is null then null else jsonb_build_object('__schema_migration_value_type__','datetime','value',to_char(t."heartbeat_at",'YYYY-MM-DD"T"HH24:MI:SS.US')) end)), '[]'::jsonb) from quant_coordination."app_runtime_status" t),
'app_state_sync',
