create or replace function public.quant_record_coordination_backup(p_result jsonb) returns void
language plpgsql security definer set search_path=pg_catalog
as $record$
begin
    if (p_result->>'tables')::integer <> 20
       or (p_result->>'compressed_bytes')::bigint not between 1 and 1048576
       or length(p_result->>'sha256') <> 64 then
        raise exception 'Invalid backup result';
    end if;
    insert into quant_cloud_jobs.coordination_backup_slots (slot, result, updated_at)
    values (extract(day from (p_result->>'created_at')::timestamptz)::integer,p_result,now())
    on conflict (slot) do update set result=excluded.result, updated_at=excluded.updated_at;
end;
$record$;
revoke all on function public.quant_record_coordination_backup(jsonb) from public, anon, authenticated;
grant execute on function public.quant_record_coordination_backup(jsonb) to service_role;

-- Scheduling and encrypted Vault values are installed by the deployment tool.
create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;
